const el=document.getElementById('app'),modalRoot=document.getElementById('modal-root');
const config=window.WMS_CONFIG||{};
let token='',state=null,view='dashboard',search='',selectedClient='',busy=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dollars=(n,currency='AED')=>`${currency} ${(Number(n||0)/100).toLocaleString('en',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const today=()=>new Date(Date.now()+4*3600000).toISOString().slice(0,10);
const roleAllowed=roles=>state&&roles.includes(state.user.role);
const management=()=>roleAllowed(['ADMIN','MANAGER']);
const fmt=n=>Number(n||0).toLocaleString('en',{maximumFractionDigits:3});
const label=v=>String(v??'').replaceAll('_',' ');
function notice(message,error=false){const toast=document.getElementById('toast');toast.textContent=message;toast.className=error?'visible error':'visible';setTimeout(()=>toast.className='',6500);}
async function api(action,input={},mutation=true){
 if(!token)throw Error('Sign in with your Google account.');
 const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(input))))).map(v=>v.toString(16).padStart(2,'0')).join('');
 const key=`wms-pending:${state?.user?.email||'session'}:${action}:${hash}`;let requestId=mutation?sessionStorage.getItem(key):null;
 if(!requestId){requestId=crypto.randomUUID();if(mutation)sessionStorage.setItem(key,requestId);}
 const response=await fetch('/api/wms',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({action,input,requestId})});
 const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Request failed. Retry to confirm the outcome.');
 if(mutation)sessionStorage.removeItem(key);return result.data;
}
async function refresh(){state=await api('snapshot',{},false);render();}
async function mutate(action,input){const result=await api(action,input);try{await refresh();}catch{notice('Saved. Refresh the page to reload the latest records.',true);}return result;}
function loginPage(message=''){
 el.innerHTML=`<main class="login"><section class="login-story"><div class="brand">YESI <span>FULFILLMENT</span></div><div><p class="eyebrow">ONE CONNECTED WAREHOUSE</p><h1>From receiving<br>to the final mile.</h1><p>Inventory, fulfillment, shipments and client accounts. Every movement recorded.</p><div class="login-stats"><span>Stock control</span><span>Verified dispatch</span><span>Client billing</span></div></div><small>Warehouse operations workspace</small></section><section class="login-form"><div><p class="eyebrow">STAFF ACCESS</p><h2>Welcome back</h2><p>Sign in with the Google account enabled by your administrator.</p><div id="google-signin"></div><p class="error-text">${esc(message)}</p>${!config.googleClientId?'<div class="setup-note"><strong>Connection setup is required</strong><p>Your IT team must configure the Google sign-in client and Sheets gateway before warehouse access is available.</p></div>':''}<small>Company access is controlled by the Users sheet.</small></div></section></main>`;
 if(!config.googleClientId)return;
 const interval=setInterval(()=>{if(window.google?.accounts?.id){clearInterval(interval);google.accounts.id.initialize({client_id:config.googleClientId,callback:async response=>{token=response.credential;try{await refresh();}catch(e){token='';loginPage(e.message);}}});google.accounts.id.renderButton(document.getElementById('google-signin'),{theme:'outline',size:'large',text:'signin_with',width:300});}},150);
 setTimeout(()=>{clearInterval(interval);if(!window.google?.accounts?.id){const target=document.querySelector('.error-text');if(target)target.textContent='Google sign-in did not load. Check your connection or browser settings.';}},15000);
}
const NAV=[['dashboard','Overview','◎'],['receiving','Receiving','↓'],['inbound','Inbound posting','⇣'],['stock','Current stock','▦'],['orders','Orders & assembly','≡'],['picks','Picking','✓'],['packing','Packing verification','▣'],['shipments','Shipments & dispatch','↗'],['returns','Returns','↩'],['billing','Invoices & accounts','₴'],['documents','Documents','▤'],['clients','Clients','◇'],['products','Products','□'],['locations','Locations','⊞'],['mappings','Assembly mappings','⇄'],['users','Staff & permissions','♙'],['reports','Reports & audit','▥']];
const descriptions={dashboard:'Live operational status from Google Sheets.',receiving:'Inspect expected, received and damaged quantities.',inbound:'Post validated stock into the movement ledger.',stock:'On hand, reserved and available quantities by position.',orders:'Import orders, expand approved assemblies and allocate stock.',picks:'Confirm the right item at its allocated location.',packing:'Verify the required units before releasing shipments.',shipments:'Prepare manifests and dispatch fully verified orders.',returns:'Receive shipped items back into stock or quarantine.',billing:'Client receivables, supplier payables and payment records.',documents:'Client invoices, delivery papers and warehouse documents.',clients:'Client records and billing currency.',products:'Warehouse articles, barcode rules and tracking requirements.',locations:'Warehouse zones and client assignments.',mappings:'Approved assembly components and quantities.',users:'Google account access and warehouse roles.',reports:'Movement exports and a record of staff actions.'};
function title(){return NAV.find(n=>n[0]===view)?.[1]||view;}
function render(){
 if(!state)return loginPage();
 const nav=NAV.filter(n=>n[0]!=='users'||state.user.role==='ADMIN').filter(n=>n[0]!=='billing'||roleAllowed(['ADMIN','MANAGER','FINANCE']));
 el.innerHTML=`<div class="layout"><aside><div class="brand">YESI <span>FULFILLMENT WMS</span></div><div class="side-caption">OPERATIONS WORKSPACE</div><nav>${nav.map(([key,name,icon])=>`<button data-nav="${key}" class="${view===key?'active':''}"><i>${icon}</i>${name}</button>`).join('')}</nav><div class="side-profile"><b>${esc(state.user.name)}</b><small>${esc(state.user.role)} · Google Sheets</small><button id="signout">Sign out</button></div></aside><div class="main"><header><span class="header-path">WAREHOUSE / ${esc(title().toUpperCase())}</span><button id="refresh" class="secondary">↻ Refresh</button></header><main><div class="page-heading"><div><p class="eyebrow">FULFILLMENT CONTROL</p><h1>${esc(title())}</h1><p>${esc(descriptions[view])}</p></div><div id="actions"></div></div>${body()}</main></div></div>`;
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;search='';render();});
 document.getElementById('signout').onclick=()=>{token='';state=null;google?.accounts?.id?.disableAutoSelect();loginPage();};
 document.getElementById('refresh').onclick=async()=>{try{await refresh();notice('Warehouse records refreshed.');}catch(e){notice(e.message,true);}};
 bindActions();bindTableActions();
 const input=document.getElementById('search');if(input)input.oninput=e=>{search=e.target.value;renderTableOnly();};
 const client=document.getElementById('client-filter');if(client)client.onchange=e=>{selectedClient=e.target.value;render();};
 document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>downloadCsv(b.dataset.export,tableData(b.dataset.export).rows));
}
function toolbar(){return `<div class="toolbar"><input id="search" type="search" placeholder="Search records…" value="${esc(search)}"><select id="client-filter"><option value="">All clients</option>${state.Clients.map(c=>`<option value="${esc(c.id)}" ${selectedClient===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button class="secondary" data-export="${view}">Export CSV</button></div>`;}
function badge(s){return `<span class="badge ${['SHIPPED','PACKED','PASSED','POSTED','ISSUED','AVAILABLE'].includes(s)?'good':['DAMAGED','CANCELLED','VOID','QUARANTINE'].includes(s)?'bad':''}">${esc(label(s))}</span>`;}
function card(k,v,note){return `<div class="metric"><small>${esc(k)}</small><b>${esc(v)}</b><span>${esc(note)}</span></div>`;}
function body(){
 if(view==='dashboard'){
  const localDay=value=>new Date(new Date(value).getTime()+4*3600000).toISOString().slice(0,10);
  const s=state.stock,inbound=state.Movements.filter(m=>m.type==='INBOUND'&&localDay(m.at)===today()).reduce((n,m)=>n+m.qty,0),outbound=state.Movements.filter(m=>m.type==='OUTBOUND'&&localDay(m.at)===today()).reduce((n,m)=>n-m.qty,0);
  return `<div class="metrics">${card('Stock on hand',fmt(s.reduce((n,r)=>n+r.qty,0)),'Recorded warehouse units')}${card('Inbound today',fmt(inbound),'Units posted to stock')}${card('Outbound today',fmt(outbound),'Units dispatched')}${card('Open order lines',state.Orders.filter(o=>!['SHIPPED','CANCELLED'].includes(o.status)).length,'Awaiting fulfillment')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2>Fulfillment pipeline</h2><span>Live queue</span></div><div class="pipeline">${['NEW','ALLOCATED','PACKED','MANIFESTED','SHIPPED'].map(status=>`<div><b>${state.Orders.filter(o=>o.status===status).length}</b><span>${label(status)}</span></div>`).join('')}</div><p class="panel-note">Receive → allocate → pick → pack → dispatch. Dispatch requires every unit to pass verification.</p></section><section class="panel"><div class="panel-heading"><h2>Expiry attention</h2></div>${tableHtml(state.stock.filter(s=>s.qty>0&&s.expiry&&s.expiry<=new Date(Date.now()+90*86400000).toISOString().slice(0,10)),['article','batch','expiry','qty'])}</section></div><section class="panel"><div class="panel-heading"><h2>Recent movements</h2><span>Newest stock activity</span></div>${tableHtml([...state.Movements].reverse().slice(0,12),['at','type','clientId','article','qty','reference'])}</section>`;
 }
 if(view==='billing')return `<div class="metrics">${[...new Set(state.balances.map(i=>i.currency))].map(currency=>card('Outstanding receivables',dollars(state.balances.filter(i=>i.direction==='RECEIVABLE'&&i.currency===currency).reduce((s,i)=>s+i.balanceMinor,0),currency),'Client balances')).join('')}${card('Invoice records',state.Invoices.length,'Receivables and payables')}</div>${toolbar()}<section class="panel" id="data-table">${table()}</section><section class="panel"><div class="panel-heading"><h2>Payment records</h2></div>${tableHtml(state.Payments,['date','clientId','invoiceId','amountMinor','currency','method','reference'])}</section>`;
 if(view==='inbound')return `<section class="info"><strong>Posting changes inventory.</strong><span>Use an existing client, product and location. Serialized items require one unique serial or IMEI per unit. Imports are checked before posting.</span></section>${toolbar()}<section class="panel" id="data-table">${table()}</section>`;
 if(view==='reports')return `${toolbar()}<section class="panel" id="data-table">${table()}</section><section class="panel"><div class="panel-heading"><h2>Staff audit trail</h2></div>${tableHtml([...state.Audit].reverse(),['at','by','role','action','records','requestId'])}</section>`;
 return `${toolbar()}<section class="panel" id="data-table">${table()}</section>`;
}
function tableData(key=view){
 const spec={receiving:['Receiving',['reference','clientId','expected','received','damaged','status','at']],inbound:['Movements',['clientId','article','qty','location','batch','expiry','serial','reference','at']],stock:['stock',['clientId','article','location','batch','expiry','serial','qty','reserved','available','blocked']],orders:['Orders',['orderNo','tracking','clientId','article','qty','status']],picks:['Picks',['article','location','qty','pickedQty','packedQty','assignedTo','status']],packing:['Picks',['article','location','qty','pickedQty','packedQty','status']],shipments:['Shipments',['reference','clientId','carrier','tracking','status','at','shippedAt']],returns:['Returns',['clientId','pickId','qty','damaged','reason','at']],billing:['balances',['invoiceNo','clientId','direction','currency','totalMinor','paidMinor','balanceMinor','status','dueDate']],documents:['Documents',['name','clientId','kind','invoiceId','shipmentId','size','at']],clients:['Clients',['id','name','contact','currency','active']],products:['Products',['id','clientId','article','description','barcode','serialized','expiryRequired','active']],locations:['Locations',['id','zone','clientId','active']],mappings:['Mappings',['clientId','assemblyArticle','productId','units','approved']],users:['Users',['email','name','role','active']],reports:['Movements',['at','type','clientId','article','location','qty','reference','by']]};
 const [source,columns]=spec[key]||['Orders',['id']];let rows=state[source]||[];if(key==='inbound')rows=rows.filter(m=>m.type==='INBOUND');if(['picks','packing'].includes(key)){rows=rows.filter(p=>!['CANCELLED','SHIPPED'].includes(p.status)).map(p=>({...p,orderNo:state.Orders.find(o=>o.id===p.orderId)?.orderNo||'',tracking:state.Orders.find(o=>o.id===p.orderId)?.tracking||''}));columns.unshift('orderNo','tracking');}
 return {rows:rows.filter(r=>(!selectedClient||!r.clientId||r.clientId===selectedClient)&&Object.values(r).join(' ').toLowerCase().includes(search.toLowerCase())),columns};
}
function table(){const {rows,columns}=tableData();return tableHtml(rows,columns,true);}
function tableHtml(rows,columns,actions=false){if(!rows.length)return `<div class="empty"><span>▦</span><h3>No records yet</h3><p>Create records or adjust your search and client filter.</p></div>`;return `<div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${esc(label(c.replace(/([A-Z])/g,' $1')))}</th>`).join('')}${actions?'<th>Action</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(c=>`<td>${c==='status'?badge(r[c]):c.endsWith('Minor')?esc(dollars(r[c],r.currency)):typeof r[c]==='boolean'?(r[c]?'Yes':'No'):esc(r[c]??'')}</td>`).join('')}${actions?`<td class="row-actions">${rowActions(r)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function renderTableOnly(){const t=document.getElementById('data-table');if(t){t.innerHTML=table();bindTableActions();}}
function rowButton(action,id,name){return `<button class="text-button" data-action="${action}" data-id="${esc(id)}">${name}</button>`;}
function rowActions(r){
 if(['clients','products','locations','mappings','users'].includes(view)&&management())return rowButton('edit',r.id,'Edit');
 if(view==='stock'&&roleAllowed(['ADMIN','MANAGER','INBOUND']))return (management()?rowButton('adjust',r.stockKey,'Adjust'):'')+rowButton('transfer',r.stockKey,'Transfer');
 if(view==='orders'&&management())return (r.status==='NEW'?rowButton('allocate',r.id,'Allocate'):'')+(!['SHIPPED','CANCELLED','MANIFESTED'].includes(r.status)?rowButton('cancel',r.id,'Cancel'):'');
 if(view==='picks'&&roleAllowed(['ADMIN','MANAGER','PICKER']))return rowButton('pick',r.id,'Confirm pick');
 if(view==='packing'&&roleAllowed(['ADMIN','MANAGER','PACKER']))return rowButton('pack',r.id,'Scan to pack');
 if(view==='shipments')return rowButton('manifest',r.id,'Manifest')+(r.status==='READY'&&roleAllowed(['ADMIN','MANAGER','DISPATCH'])?rowButton('dispatch',r.id,'Dispatch'):'');
 if(view==='billing')return rowButton('printInvoice',r.id,'Print invoice')+(r.balanceMinor>0?rowButton('payment',r.id,'Record payment'):'');
 if(view==='documents')return rowButton('download',r.id,'Download');return '';
}
function bindActions(){
 const specs={receiving:['New inspection','receiving'],inbound:['Post inbound file','inbound'],orders:['Import orders','orders'],shipments:['Create shipment','shipment'],returns:['Receive return','return'],billing:['Create invoice','invoice'],documents:['Upload document','document'],clients:['Add client','client'],products:['Add product','product'],locations:['Add location','location'],mappings:['Add mapping','mapping'],users:['Add staff account','user']};
 const allowed={receiving:['ADMIN','MANAGER','INBOUND'],inbound:['ADMIN','MANAGER','INBOUND'],orders:['ADMIN','MANAGER'],shipments:['ADMIN','MANAGER','DISPATCH'],returns:['ADMIN','MANAGER','INBOUND'],billing:['ADMIN','MANAGER','FINANCE'],documents:['ADMIN','MANAGER','INBOUND','DISPATCH','FINANCE'],clients:['ADMIN','MANAGER'],products:['ADMIN','MANAGER'],locations:['ADMIN','MANAGER'],mappings:['ADMIN','MANAGER'],users:['ADMIN']};
 const target=document.getElementById('actions');if(specs[view]&&roleAllowed(allowed[view])){const [name,type]=specs[view];target.innerHTML=`<button class="primary" id="create">＋ ${name}</button>`;document.getElementById('create').onclick=()=>openForm(type);}
 if(view==='orders'&&management()){target.insertAdjacentHTML('beforeend',' <button class="secondary" id="allocate-batch">Allocate new lines</button>');document.getElementById('allocate-batch').onclick=async()=>{try{if(!selectedClient)throw Error('Select a client before bulk allocation.');const ids=state.Orders.filter(o=>o.clientId===selectedClient&&o.status==='NEW').slice(0,200).map(o=>o.id);if(!ids.length)throw Error('No new order lines for this client.');await mutate('pick.allocate.batch',{orderIds:ids});notice(`${ids.length} order lines allocated.`);}catch(e){notice(e.message,true);}};}
}
const f=(name,label,type='text',options=null,required=true,value='')=>({name,label,type,options,required,value});
const selectRows=(rows,label='name')=>rows.filter(r=>r.active!==false).map(r=>[r.id,r[label]||r.article||r.id]);
function fields(type,row={}){
 const clients=selectRows(state.Clients),products=state.Products.filter(p=>p.active!==false).map(p=>[p.id,`${p.clientId} · ${p.article}`]),locations=selectRows(state.Locations,'id');
 const spec={
 client:[f('id','Client ID'),f('name','Client name'),f('contact','Contact email / phone','text',null,false),f('currency','Currency','text',null,true,'AED'),f('active','Active','checkbox',null,false,true)],
 product:[f('id','Product ID (leave blank for new)','text',null,false),f('clientId','Client','select',clients),f('article','Warehouse article'),f('description','Description'),f('barcode','Barcode / UPC','text',null,false),f('serialized','Serialized item','checkbox',null,false,false),f('expiryRequired','Require batch and expiry','checkbox',null,false,false),f('active','Active','checkbox',null,false,true)],
 location:[f('id','Location code'),f('zone','Zone','text',null,true,'GENERAL'),f('clientId','Assigned client (optional)','select',clients,false),f('active','Active','checkbox',null,false,true)],
 mapping:[f('id','Mapping ID (new: leave blank)','text',null,false),f('assemblyArticle','Assembly article'),f('productId','Component product','select',products),f('units','Component units','number',null,true,1),f('approved','Approved for fulfillment','checkbox',null,false,false)],
 user:[f('email','Google account email','email'),f('name','Staff name'),f('role','Role','select',['ADMIN','MANAGER','INBOUND','PICKER','PACKER','DISPATCH','FINANCE','VIEWER'].map(r=>[r,r])),f('active','Active','checkbox',null,false,true)],
 receiving:[f('clientId','Client','select',clients),f('reference','Receipt reference'),f('expected','Expected quantity','number'),f('received','Received quantity','number'),f('damaged','Damaged units (included in received)','number',null,true,0)],
 adjust:[f('stockKey','Stock position','text',null,true,row.stockKey||''),f('qty','Adjustment (+ adds, − removes)','number'),f('reason','Reason','textarea')],
 transfer:[f('stockKey','Stock position','text',null,true,row.stockKey||''),f('location','Destination location','select',locations),f('qty','Transfer quantity','number',null,true,1),f('reference','Transfer reference')],
 allocate:[f('orderId','Order line ID','text',null,true,row.id||''),f('assignedTo','Assigned picker (optional)','select',(state.staff||[]).map(u=>[u.email,u.name]),false)],
 cancel:[f('orderId','Order line ID','text',null,true,row.id||''),f('reason','Cancellation reason','textarea')],
 pick:[f('pickId','Pick task ID','text',null,true,row.id||''),f('code','Scan serial / IMEI or article / barcode'),f('qty','Quantity','number',null,true,1)],
 pack:[f('pickId','Pick task ID','text',null,true,row.id||''),f('tracking','Scan order tracking label'),f('code','Scan serial / IMEI or article / barcode'),f('qty','Quantity','number',null,true,1)],
 shipment:[f('orderIds','Packed order lines (large selections split into manifest parts)','multiselect',state.Orders.filter(o=>o.status==='PACKED').map(o=>[o.id,`${o.clientId} · ${o.orderNo} · ${o.article} · ${o.qty}`])),f('reference','Shipment / container reference'),f('carrier','Carrier'),f('tracking','Shipment tracking / bill of lading','text',null,false)],
 return:[f('pickId','Shipped pick task','select',state.Picks.filter(p=>p.status==='SHIPPED').map(p=>[p.id,`${p.clientId} · ${p.article} · ${p.qty}`])),f('qty','Returned quantity','number',null,true,1),f('damaged','Quarantine damaged goods','checkbox',null,false,false),f('reason','Return reason','textarea')],
 payment:[f('invoiceId','Invoice','select',state.balances.filter(i=>i.balanceMinor>0).map(i=>[i.id,`${i.clientId} · ${i.invoiceNo} · ${dollars(i.balanceMinor,i.currency)}`]),true,row.id||''),f('amount','Amount','number'),f('reference','Bank / payment reference'),f('method','Method','select',[['BANK','Bank transfer'],['CASH','Cash'],['CARD','Card'],['OTHER','Other']]),f('date','Payment date','date',null,true,today())],
 document:[f('clientId','Client','select',clients),f('invoiceId','Related invoice (optional)','select',state.Invoices.map(i=>[i.id,`${i.clientId} · ${i.invoiceNo}`]),false),f('shipmentId','Related shipment (optional)','select',state.Shipments.map(s=>[s.id,`${s.clientId} · ${s.reference}`]),false),f('kind','Document type','select',[['DOCUMENT','General document'],['DELIVERY','Delivery note'],['BILL_OF_LADING','Bill of lading'],['CUSTOMS','Customs document']]),f('file','PDF, image or XLSX (maximum 4 MB)','file')],
 invoice:[f('clientId','Client','select',clients),f('direction','Account direction','select',[['RECEIVABLE','Client receivable'],['PAYABLE','Supplier payable']]),f('invoiceNo','Invoice number'),f('currency','Currency','text',null,true,'AED'),f('issuedDate','Invoice date','date',null,true,today()),f('dueDate','Due date','date',null,true,today()),f('items','Invoice lines CSV: description,qty,unitPrice,taxRate','textarea')],
 inbound:[f('clientId','Client','select',clients),f('reference','Unique inbound reference'),f('file','Upload CSV file','file',null,false),f('rows','Stock rows CSV: article,qty,location,batch,expiry,serial','textarea',null,false)],
 orders:[f('clientId','Client','select',clients),f('file','Upload CSV file','file',null,false),f('rows','Order rows CSV: orderNo,tracking,article,qty','textarea',null,false)]
 };
 return (spec[type]||[]).map(field=>({...field,value:type==='pack'&&field.name==='tracking'?'':row[field.name]??field.value}));
}
function fieldHtml(field){const {name,label,type,options,required,value}=field;const attrs=`name="${name}" ${required?'required':''}`;
 let html;if(type==='checkbox')html=`<input ${attrs} type="checkbox" ${value?'checked':''}>`;
 else if(type==='select'||type==='multiselect')html=`<select ${attrs} ${type==='multiselect'?'multiple size="7"':''}><option value="">${required?'Select…':'None'}</option>${options.map(([v,n])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`).join('')}</select>`;
 else if(type==='textarea')html=`<textarea ${attrs} rows="5">${esc(value)}</textarea>`;
 else html=`<input ${attrs} type="${type}" ${type==='number'?'step="0.001"':''} ${type==='file'?'accept=".csv,.pdf,.png,.jpg,.jpeg,.xlsx"':`value="${esc(value)}"`}>`;
 return `<label class="field ${type==='textarea'||type==='multiselect'?'wide':''} ${type==='checkbox'?'check':''}"><span>${esc(label)}</span>${html}</label>`;
}
function openForm(type,row={}){
 const spec=fields(type,row);modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal"><div class="modal-heading"><div><p class="eyebrow">WAREHOUSE RECORD</p><h2>${esc(label(type.toUpperCase()))}</h2></div><button type="button" class="secondary" id="close-modal">✕</button></div><form id="record-form"><div class="fields">${spec.map(fieldHtml).join('')}</div>${['inbound','orders','invoice'].includes(type)?`<button type="button" id="download-template" class="secondary">Download CSV header template</button>`:''}<p id="form-error" class="error-text" role="alert"></p><p id="progress"></p><div class="modal-footer"><button type="button" class="secondary" id="cancel-modal">Cancel</button><button type="submit" class="primary" id="submit-form">${['inbound','orders'].includes(type)?'Validate and import':'Save record'}</button></div></form></section></div>`;
 const close=()=>{if(!busy)modalRoot.innerHTML='';};document.getElementById('close-modal').onclick=close;document.getElementById('cancel-modal').onclick=close;
 const template=document.getElementById('download-template');if(template)template.onclick=()=>downloadText(type+'-template.csv',type==='inbound'?'article,qty,location,batch,expiry,serial\n':type==='orders'?'orderNo,tracking,article,qty\n':'description,qty,unitPrice,taxRate\n','text/csv');
 const form=document.getElementById('record-form');form.onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;const button=document.getElementById('submit-form');button.disabled=true;button.textContent='Saving…';document.getElementById('form-error').textContent='';
  try{const input={};for(const field of spec){const element=form.elements.namedItem(field.name);input[field.name]=field.type==='checkbox'?element.checked:field.type==='number'?Number(element.value):field.type==='file'?element.files[0]:field.type==='multiselect'?[...element.selectedOptions].map(o=>o.value).filter(Boolean):element.value;}
   const action={client:'client.save',product:'product.save',location:'location.save',mapping:'mapping.save',user:'user.save',receiving:'receiving.save',adjust:'stock.adjust',transfer:'stock.transfer',allocate:'pick.allocate',cancel:'order.cancel',pick:'pick.confirm',pack:'pack.scan',shipment:'shipment.create',return:'return.receive',payment:'payment.record',invoice:'invoice.create',document:'document.upload'}[type];
   if(type==='document'){const file=input.file;if(!file||file.size>4000000)throw Error('Choose a file up to 4 MB.');input.base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});input.name=file.name;input.mime=file.type||'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';delete input.file;await mutate(action,input);}
   else if(type==='shipment'){
    if(!input.orderIds.length)throw Error('Select packed order lines.');const clients=new Set(state.Orders.filter(o=>input.orderIds.includes(o.id)).map(o=>o.clientId));if(clients.size!==1)throw Error('Select packed orders from one client only.');
    const prefix=JSON.stringify(input);const key='wms-shipment-parts:'+state.user.email+':'+prefix;let completed=Number(sessionStorage.getItem(key)||0);const parts=Math.ceil(input.orderIds.length/200);
    for(let part=completed;part<parts;part++){document.getElementById('progress').textContent=`Creating manifest part ${part+1} of ${parts}…`;await api(action,{...input,reference:parts===1?input.reference:`${input.reference} / part ${part+1}`,orderIds:input.orderIds.slice(part*200,(part+1)*200)});sessionStorage.setItem(key,String(part+1));}sessionStorage.removeItem(key);await refresh();
   }
   else if(type==='inbound'||type==='orders'){
    const source=input.file?await input.file.text():input.rows;if(!source.trim())throw Error('Choose a CSV file or paste rows with a header.');const parsed=parseCsv(source);if(!parsed.length)throw Error('No data rows found.');const needed=type==='inbound'?['article','qty','location']:['orderNo','tracking','article','qty'];if(needed.some(k=>!(k in parsed[0])))throw Error('CSV headers do not match the template.');
    const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify({type,clientId:input.clientId,reference:input.reference,parsed}))))).map(x=>x.toString(16).padStart(2,'0')).join('');
    const progressKey=`wms-bulk:${state.user.email}:${digest}`;let completed=Number(sessionStorage.getItem(progressKey)||0);
    for(let offset=completed*200;offset<parsed.length;offset+=200){document.getElementById('progress').textContent=`Processing rows ${offset+1}–${Math.min(offset+200,parsed.length)} of ${parsed.length}…`;await api(type==='inbound'?'inbound.post':'orders.import',{clientId:input.clientId,...(type==='inbound'?{reference:input.reference+' / part '+(Math.floor(offset/200)+1)}:{}),rows:parsed.slice(offset,offset+200)});sessionStorage.setItem(progressKey,String(Math.floor(offset/200)+1));}await refresh();sessionStorage.removeItem(progressKey);
   }else{if(type==='invoice'){input.items=parseCsv(input.items);if(!input.items.length)throw Error('Add invoice lines using the CSV header template.');}await mutate(action,input);}
   busy=false;close();notice('Records saved to Google Sheets.');
  }catch(e){document.getElementById('form-error').textContent=e.message;button.textContent='Retry / save';}finally{busy=false;button.disabled=false;}
 };
}
function bindTableActions(){document.querySelectorAll('[data-action]').forEach(button=>button.onclick=async()=>{
 const action=button.dataset.action,id=button.dataset.id;const source=tableData().rows;const row=source.find(r=>r.id===id||r.stockKey===id);
 try{
  if(action==='edit'){const type={clients:'client',products:'product',locations:'location',mappings:'mapping',users:'user'}[view];openForm(type,row);}
  else if(['adjust','transfer','allocate','cancel','pick','pack','payment'].includes(action))openForm(action,row);
  else if(action==='dispatch'){if(!confirm('Dispatch this shipment and deduct its verified stock?'))return;button.disabled=true;await mutate('shipment.dispatch',{shipmentId:id});notice('Shipment dispatched and stock updated.');}
  else if(action==='manifest'){const ids=new Set(row.orderIds);downloadCsv('shipment-'+row.reference,state.Orders.filter(o=>ids.has(o.id)));}
  else if(action==='download'){button.disabled=true;const file=await api('document.download',{documentId:id},false);const bytes=Uint8Array.from(atob(file.base64),c=>c.charCodeAt(0));downloadBlob(file.name,new Blob([bytes],{type:file.mime}));}
  else if(action==='printInvoice'){const client=state.Clients.find(c=>c.id===row.clientId);const win=window.open('','_blank');if(!win)throw Error('Allow a new window to print the invoice.');win.document.write(`<!doctype html><html><head><title>${esc(row.invoiceNo)}</title><link rel="stylesheet" href="/invoice.css"></head><body><h1>${esc(config.companyName||'YESI Fulfillment')}</h1><h2>Invoice ${esc(row.invoiceNo)}</h2><p>Client: ${esc(client?.name)}<br>Date: ${esc(row.issuedDate)}<br>Due: ${esc(row.dueDate)}<br>Account: ${esc(row.direction)}</p><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Tax %</th><th>Total</th></tr></thead><tbody>${row.items.map(i=>`<tr><td>${esc(i.description)}</td><td>${i.qty}</td><td>${esc(dollars(Math.round(i.unitPrice*100),row.currency))}</td><td>${i.taxRate}</td><td>${esc(dollars(i.lineMinor+i.lineTax,row.currency))}</td></tr>`).join('')}</tbody></table><p>Subtotal: ${esc(dollars(row.subtotalMinor,row.currency))}<br>Tax: ${esc(dollars(row.taxMinor,row.currency))}<br><strong>Total: ${esc(dollars(row.totalMinor,row.currency))}</strong><br>Balance: ${esc(dollars(row.balanceMinor,row.currency))}</p><p>Use your browser’s Print command to print or save as PDF.</p></body></html>`);win.document.close();}
 }catch(e){notice(e.message,true);}finally{button.disabled=false;}
 });}
function parseCsv(text){const matrix=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))matrix.push(row);row=[];cell='';}else cell+=c;}if(quote)throw Error('CSV has an unclosed quote.');row.push(cell);if(row.some(x=>x.trim()))matrix.push(row);const headers=(matrix.shift()||[]).map(s=>s.replace(/^\uFEFF/,'').trim());return matrix.map((r,index)=>{if(r.length!==headers.length)throw Error(`CSV row ${index+2} has the wrong number of columns.`);return Object.fromEntries(headers.map((h,i)=>[h,r[i].trim()]));});}
function downloadBlob(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name.replace(/[\/\\]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function downloadText(name,text,mime){downloadBlob(name,new Blob([text],{type:mime}));}
function downloadCsv(name,rows){if(!rows.length)return notice('No records to export.');const cols=[...new Set(rows.flatMap(Object.keys))];const quote=v=>{let s=String(v??'');if(typeof v==='string'&&/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};downloadText(name+'.csv',[cols.map(quote).join(','),...rows.map(r=>cols.map(c=>quote(typeof r[c]==='object'?JSON.stringify(r[c]):r[c])).join(','))].join('\r\n'),'text/csv');}
